import{_ as s,a0 as p,w as l,s as d,ao as u,I as o,a1 as a,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何修復 ubuntu 中檢測到系統程序錯誤的問題 | LCTT x X-CMD","titleTemplate":false,"description":"如何修復 ubuntu 中檢測到系統程序錯誤的問題 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修復 ubuntu 中檢測到系統程序錯誤的問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修復 ubuntu 中檢測到系統程序錯誤的問題 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04","title":"如何修復 ubuntu 中檢測到系統程序錯誤的問題","tag":"201507","desc":""},"relativePath":"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04.md","filePath":"[post].md"}'),i={name:"201507/20150713 How To Fix System Program Problem Detected In Ubuntu 14.04.md"};function b(m,t,h,f,g,T){const r=p("Link");return l(),d("div",null,[t[17]||(t[17]=u('<h1 id="如何修復-ubuntu-中檢測到系統程序錯誤的問題" tabindex="-1">如何修復 ubuntu 中檢測到系統程序錯誤的問題 <a class="header-anchor" href="#如何修復-ubuntu-中檢測到系統程序錯誤的問題" aria-label="Permalink to “如何修復 ubuntu 中檢測到系統程序錯誤的問題”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/system_program_Problem_detected.jpeg" alt=""></p><p>在過去的幾個星期，（幾乎）每次都有消息 <strong>Ubuntu 15.04在啓動時檢測到系統程序錯誤</strong> 跑出來“歡迎”我。那時我是直接忽略掉它的，但是這種情況到了某個時刻，它就讓人覺得非常煩人了！</p><blockquote><p>檢測到系統程序錯誤(System program problem detected)</p><p>你想立即報告這個問題嗎？</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/System_Program_Problem_Detected.png" alt=""></p></blockquote><p>我肯定地知道如果你是一個Ubuntu用户，你可能曾經也遇到過這個惱人的彈窗。在本文中，我們將探討在Ubuntu 14.04和15.04中遇到&quot;檢測到系統程序錯誤(system program problem detected)&quot;時 應該怎麼辦。</p><h3 id="怎麼解決ubuntu中-檢測到系統程序錯誤-的錯誤" tabindex="-1">怎麼解決Ubuntu中&quot;檢測到系統程序錯誤&quot;的錯誤 <a class="header-anchor" href="#怎麼解決ubuntu中-檢測到系統程序錯誤-的錯誤" aria-label="Permalink to “怎麼解決Ubuntu中檢測到系統程序錯誤的錯誤”">​</a></h3><h4 id="那麼這個通知到底是關於什麼的" tabindex="-1">那麼這個通知到底是關於什麼的？ <a class="header-anchor" href="#那麼這個通知到底是關於什麼的" aria-label="Permalink to “那麼這個通知到底是關於什麼的？”">​</a></h4><p>大體上講，它是在告知你，你的系統的一部分崩潰了。可別因為“崩潰”這個詞而恐慌。這不是一個嚴重的問題，你的系統還是完完全全可用的。只是在之前的某個時刻某個程序崩潰了，而Ubuntu想讓你決定要不要把這個問題報告給開發者，這樣他們就能夠修復這個問題。</p><h4 id="那麼-我們點了-報告錯誤-的按鈕後-它以後就不再顯示了" tabindex="-1">那麼，我們點了“報告錯誤”的按鈕後，它以後就不再顯示了？#### <a class="header-anchor" href="#那麼-我們點了-報告錯誤-的按鈕後-它以後就不再顯示了" aria-label="Permalink to “那麼，我們點了“報告錯誤”的按鈕後，它以後就不再顯示了？####”">​</a></h4><p>不，不是的！即使你點了“報告錯誤”按鈕，最後你還是會被一個如下的彈窗再次“歡迎”一下：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Ubuntu_Internal_error.png" alt=""></p>',11)),o("p",null,[a(r,{href:"http://itsfoss.com/how-to-solve-sorry-ubuntu-12-04-has-experienced-an-internal-error/"},{default:n(()=>[...t[0]||(t[0]=[e("對不起，Ubuntu發生了一個內部錯誤",-1)])]),_:1}),t[2]||(t[2]=e("是個Apport（LCTT 譯註：Apport是Ubuntu中錯誤信息的收集報告系統，詳見Ubuntu Wiki中的Apport篇），它將會進一步的打開網頁瀏覽器，然後你可以通過登錄或創建",-1)),a(r,{href:"https://launchpad.net/"},{default:n(()=>[...t[1]||(t[1]=[e("Launchpad",-1)])]),_:1}),t[3]||(t[3]=e("帳户來填寫一份漏洞（Bug)報告文件。你看，這是一個複雜的過程，它要花整整四步來完成。",-1))]),t[18]||(t[18]=u(`<h4 id="但是我想幫助開發者-讓他們知道這個漏洞啊" tabindex="-1">但是我想幫助開發者，讓他們知道這個漏洞啊 !#### <a class="header-anchor" href="#但是我想幫助開發者-讓他們知道這個漏洞啊" aria-label="Permalink to “但是我想幫助開發者，讓他們知道這個漏洞啊 !####”">​</a></h4><p>你這樣想的確非常地周到體貼,而且這樣做也是正確的。但是這樣做的話，存在兩個問題。第一，存在非常高的概率，這個漏洞已經被報告過了；第二，即使你報告了個這次崩潰，也無法保證你不會再看到它。</p><h4 id="那麼-你的意思就是説別報告這次崩潰了" tabindex="-1">那麼，你的意思就是説別報告這次崩潰了？#### <a class="header-anchor" href="#那麼-你的意思就是説別報告這次崩潰了" aria-label="Permalink to “那麼，你的意思就是説別報告這次崩潰了？####”">​</a></h4><p>對，也不對。如果你想的話，在你第一次看到它的時候報告它。你可以在上面圖片顯示的“顯示細節（Show Details)”中，查看崩潰的程序。但是如果你總是看到它，或者你不想報告漏洞（Bug)，那麼我建議你還是一次性擺脱這個問題吧。</p><h3 id="修復ubuntu中-檢測到系統程序錯誤-的錯誤" tabindex="-1">修復Ubuntu中“檢測到系統程序錯誤”的錯誤 <a class="header-anchor" href="#修復ubuntu中-檢測到系統程序錯誤-的錯誤" aria-label="Permalink to “修復Ubuntu中“檢測到系統程序錯誤”的錯誤”">​</a></h3><p>這些錯誤報告被存放在Ubuntu中目錄/var/crash中。如果你翻看這個目錄的話，應該可以看到有一些以crash結尾的文件。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/07/Crash_reports_Ubuntu.jpeg" alt=""></p><p>我的建議是刪除這些錯誤報告。打開一個終端，執行下面的命令：</p><pre><code>sudo rm /var/crash/*
</code></pre><p>這個操作會刪除所有在/var/crash目錄下的所有內容。這樣你就不會再被這些報告以前程序錯誤的彈窗所擾。但是如果又有一個程序崩潰了，你就會再次看到“檢測到系統程序錯誤”的錯誤。你可以再次刪除這些報告文件，或者你可以禁用Apport來徹底地擺脱這個錯誤彈窗。</p><h4 id="徹底地擺脱ubuntu中的系統錯誤彈窗" tabindex="-1">徹底地擺脱Ubuntu中的系統錯誤彈窗 <a class="header-anchor" href="#徹底地擺脱ubuntu中的系統錯誤彈窗" aria-label="Permalink to “徹底地擺脱Ubuntu中的系統錯誤彈窗”">​</a></h4><p>如果你這樣做，系統中任何程序崩潰時，系統都不會再通知你。如果你想問問我的看法的話，我會説，這不是一件壞事，除非你願意填寫錯誤報告。如果你不想填寫錯誤報告，那麼這些錯誤通知存不存在都不會有什麼區別。</p><p>要禁止Apport，並且徹底地擺脱Ubuntu系統中的程序崩潰報告，打開一個終端，輸入以下命令：</p><pre><code>gksu gedit /etc/default/apport
</code></pre><p>這個文件的內容是：</p><pre><code># 設置0表示禁用Apportw，或者1開啓它。
# 你可以用下面的命令暫時關閉它：
# sudo service apport start force_start=1
enabled=1
</code></pre><p>把<strong>enabled=1</strong>改為<strong>enabled=0</strong>。保存並關閉文件。完成之後你就再也不會看到彈窗報告錯誤了。很顯然，如果我們想重新開啓錯誤報告功能，只要再打開這個文件，把enabled設置為1就可以了。</p><h4 id="你的有效嗎" tabindex="-1">你的有效嗎？ <a class="header-anchor" href="#你的有效嗎" aria-label="Permalink to “你的有效嗎？”">​</a></h4><p>我希望這篇教程能夠幫助你修復Ubuntu 14.04和Ubuntu 15.04中檢測到系統程序錯誤的問題。如果這個小竅門幫你擺脱了這個煩人的問題，請讓我知道。</p><hr>`,20)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),a(r,{href:"http://itsfoss.com/how-to-fix-system-program-problem-detected-ubuntu/"},{default:n(()=>[...t[4]||(t[4]=[e("http://itsfoss.com/how-to-fix-system-program-problem-detected-ubuntu/",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("作者：",-1)),a(r,{href:"http://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[6]||(t[6]=[e("Abhishek",-1)])]),_:1}),t[10]||(t[10]=e(" 譯者：",-1)),a(r,{href:"https://github.com/XLCYun"},{default:n(()=>[...t[7]||(t[7]=[e("XLCYun",-1)])]),_:1}),t[11]||(t[11]=e(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原創翻譯，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...t[13]||(t[13]=[e("Linux中國",-1)])]),_:1}),t[16]||(t[16]=e(" 榮譽推出",-1))])])}const U=s(i,[["render",b]]);export{P as __pageData,U as default};
